def removeDuplicates(nums):
    # Set to store unique elements
    seen = set()
    # List to store unique values in insertion order
    unique_elements = []
    for num in nums:
        if num not in seen:
            seen.add(num)
            unique_elements.append(num)
    # Overwrite the original array with unique elements
    for i in range(len(unique_elements)):
        nums[i] = unique_elements[i]
    # Return the count of unique elements
    return len(unique_elements)

def findMaxConsecutiveOnes(nums):
    # Variable to track maximum count of ones
    max_count = 0
    # Loop over all possible starting positions
    for i in range(len(nums)):
        # If current element is not 1, skip
        if nums[i] != 1:
            continue
        # Count consecutive ones starting from index i
        current_count = 0
        for j in range(i, len(nums)):
            if nums[j] == 1:
                current_count += 1
            else:
                break
        # Update the max count found so far
        max_count = max(max_count, current_count)
    # Return the maximum consecutive ones count
    return max_count

def findPlatform(arr, dep, n):
    # Variable to store minimum platforms needed
    max_platforms = 0
    # Loop over each arrival and departure interval
    for i in range(n):
        # Count overlaps for interval of train i
        overlaps = 1
        for j in range(n):
            if i != j:
                # Check if train j is present at station when train i arrives
                if arr[i] >= arr[j] and arr[i] <= dep[j]:
                    overlaps += 1
        # Update maximum platform count
        max_platforms = max(max_platforms, overlaps)
    # Return the maximum platforms needed
    return max_platforms

def minCoinsBruteForce(coins, V):
    # Recursive function to find the minimum coins needed
    def solve(v):
        # Base Case: if target value is 0, we need 0 coins
        if v == 0:
            return 0
        # Initialize result as infinity
        res = float('inf')
        # Try every coin that is smaller than or equal to current v
        for coin in coins:
            # If coin is less than or equal to current value v
            if coin <= v:
                # Compute min coins for remaining value
                sub_res = solve(v - coin)
                # If subproblem has a valid solution, update res
                if sub_res != float('inf') and sub_res + 1 < res:
                    res = sub_res + 1
        # Return the minimum result found
        return res
    # Return the result from recursive solver
    return solve(V)

def getPermutationBrute(n, k):
    # Generate all permutations recursively
    def generate(nums):
        if len(nums) == 0:
            return [[]]
        res = []
        for i in range(len(nums)):
            current = nums[i]
            remaining = nums[:i] + nums[i+1:]
            for p in generate(remaining):
                res.append([current] + p)
        return res
    # List of numbers
    nums = [str(i) for i in range(1, n + 1)]
    # Generate all permutations
    all_perms = generate(nums)
    # Sort permutations
    all_perms.sort()
    # Return the k-th permutation
    return "".join(all_perms[k - 1])

# Brute force represents trying all possible digit assignments
# and then verifying validity. Since it is extremely slow, we represent the outline:
def solveSudokuBrute(board):
    # Helper to check if the entire board is valid
    def isBoardValid():
        # Check row, col, and box rules for all cells
        return True
    # Place digits recursively and check validity at the end
    def backtrack(r, c):
        if r == 9:
            return isBoardValid()
        next_r = r + 1 if c == 8 else r
        next_c = 0 if c == 8 else c + 1
        if board[r][c] != '.':
            return backtrack(next_r, next_c)
        for digit in '123456789':
            board[r][c] = digit
            if backtrack(next_r, next_c):
                return True
            board[r][c] = '.'
        return False
    backtrack(0, 0)

def solveSudoku(board):
    # Helper function to check if placing char 'c' is valid
    def isValid(row, col, c):
        # Check row, column and 3x3 grid
        for i in range(9):
            # Check row for duplicate
            if board[i][col] == c:
                return False
            # Check column for duplicate
            if board[row][i] == c:
                return False
            # Check 3x3 box for duplicate
            box_row = 3 * (row // 3) + i // 3
            box_col = 3 * (col // 3) + i % 3
            if board[box_row][box_col] == c:
                return False
        return True

    # Main recursive solver function
    def solve():
        for i in range(len(board)):
            for j in range(len(board[0])):
                # Check if cell is empty
                if board[i][j] == '.':
                    # Try placing characters '1' to '9'
                    for c in '123456789':
                        # If valid to place
                        if isValid(i, j, c):
                            # Place character on the board
                            board[i][j] = c
                            # Recurse to solve next cells
                            if solve():
                                return True
                            else:
                                # Backtrack: reset cell if it fails later
                                board[i][j] = '.'
                    # Return False if no character 1-9 fits here
                    return False
        # Board is completely solved
        return True

    # Trigger the solver
    solve()

def graphColoringBrute(graph, m, N):
    # Helper to check if current coloring is valid
    def isValid(color):
        for i in range(N):
            for j in range(N):
                # If there is an edge and colors are identical, invalid
                if graph[i][j] == 1 and color[i] == color[j] and i != j:
                    return False
        return True

    # Recurse to try all colorings
    def solve(vertex, color):
        if vertex == N:
            return isValid(color)

        # Try all colors for current vertex
        for col in range(1, m + 1):
            color[vertex] = col
            if solve(vertex + 1, color):
                return True
            color[vertex] = 0
        return False

    color = [0] * N
    return solve(0, color)

def graphColoring(graph, m, N):
    # Array to store color assigned to each vertex
    color = [0] * N

    # Helper function to check if it's safe to color vertex 'v' with color 'col'
    def isSafe(v, col):
        # Check all other vertices
        for i in range(N):
            # If there is an edge and the neighbor has the same color, it is not safe
            if graph[v][i] == 1 and color[i] == col:
                return False
        # Safe to color
        return True

    # Recursive function to solve coloring problem
    def solve(v):
        # Base Case: If all vertices are colored, return True
        if v == N:
            return True
        # Try different colors for vertex v
        for col in range(1, m + 1):
            # Check if assigning color 'col' is safe
            if isSafe(v, col):
                # Assign color to vertex v
                color[v] = col
                # Recurse to color the rest of the vertices
                if solve(v + 1):
                    return True
                # Backtrack: Reset color assignment
                color[v] = 0
        # If no color can be assigned, return False
        return False

    # Start solver from vertex 0
    return solve(0)

# Simple outline of brute force representing random path walks:
def findPathBrute(m, n):
    result = []
    def dfs(row, col, path):
        # Check if out of bounds or visited or blocked
        if row < 0 or row >= n or col < 0 or col >= n or m[row][col] == 0:
            return
        if row == n-1 and col == n-1:
            result.append(path)
            return
        # Try walking without tracking coordinates strictly inside a visited matrix
        # (might loop infinitely if we don't prevent cycles)
    return result

def wordBreakBrute(s, wordDict):
    # Set for O(1) word validation
    word_set = set(wordDict)
    # Recursive helper
    def solve(start):
        # Base case: reached end of string
        if start == len(s):
            return True
        # Try all possible ending indices for current word segment
        for end in range(start + 1, len(s) + 1):
            # If current substring is in dict, solve recursively for remaining
            if s[start:end] in word_set:
                if solve(end):
                    return True
        # Return False if no valid partition works
        return False
    return solve(0)

def NthRootBrute(n, m):
    # Iterate starting from 1
    for i in range(1, m + 1):
        # Calculate power i^n
        val = i ** n
        # If we reach target, return i
        if val == m:
            return i
        # If we exceed target, root cannot be an integer
        elif val > m:
            return -1
    return -1

def findMedianSortedArraysBrute(nums1, nums2):
    m, n = len(nums1), len(nums2)
    merged = []
    i, j = 0, 0
    # Merge elements from both arrays in sorted order
    while i < m and j < n:
        if nums1[i] < nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1
    # Append remaining elements
    while i < m:
        merged.append(nums1[i])
        i += 1
    while j < n:
        merged.append(nums2[j])
        j += 1

    total_len = len(merged)
    # Calculate median based on size
    if total_len % 2 == 1:
        return float(merged[total_len // 2])
    else:
        return (merged[total_len // 2 - 1] + merged[total_len // 2]) / 2.0

