class MyStack:
    def __init__(self):
        # Primary queue
        self.q1 = deque()
        # Helper queue
        self.q2 = deque()

    def push(self, x: int) -> None:
        # Push element to q2
        self.q2.append(x)
        # Move all elements from q1 to q2
        while self.q1:
            self.q2.append(self.q1.popleft())
        # Swap names of q1 and q2
        self.q1, self.q2 = self.q2, self.q1

    def pop(self) -> int:
        # Pop from q1
        if not self.q1:
            return -1
        return self.q1.popleft()

    def top(self) -> int:
        # Peek from q1
        if not self.q1:
            return -1
        return self.q1[0]

from collections import deque

class MyStack:
    def __init__(self):
        # Use collections.deque as the underlying queue
        self.q = deque()

    def push(self, x: int) -> None:
        # Add element to the queue
        self.q.append(x)
        # Rotate all previous elements to the back of the queue
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())

    def pop(self) -> int:
        # Remove and return the front element of the queue
        if not self.q:
            return -1
        return self.q.popleft()

    def top(self) -> int:
        # Peek and return the front element of the queue
        if not self.q:
            return -1
        return self.q[0]

    def empty(self) -> bool:
        # Return true if queue length is 0
        return len(self.q) == 0

class MyQueue:
    def __init__(self):
        # Main stack
        self.s1 = []
        # Helper stack
        self.s2 = []

    def push(self, x: int) -> None:
        # Move all elements from s1 to s2
        while self.s1:
            self.s2.append(self.s1.pop())
        # Push new element to s1
        self.s1.append(x)
        # Move elements back to s1
        while self.s2:
            self.s1.append(self.s2.pop())

    def pop(self) -> int:
        # Pop top element
        if not self.s1:
            return -1
        return self.s1.pop()

    def peek(self) -> int:
        # Return top element
        if not self.s1:
            return -1
        return self.s1[-1]

class MyQueue:
    def __init__(self):
        # Stack to handle incoming elements
        self.input_stack = []
        # Stack to handle outgoing elements
        self.output_stack = []

    def push(self, x: int) -> None:
        # Push element to the input stack
        self.input_stack.append(x)

    def pop(self) -> int:
        # Ensure the output stack is not empty
        if not self.output_stack:
            # Transfer elements from input to output in reverse order
            while self.input_stack:
                self.output_stack.append(self.input_stack.pop())
        # Return and remove the top of output stack
        if not self.output_stack:
            return -1
        return self.output_stack.pop()

    def peek(self) -> int:
        # Ensure the output stack has the current elements
        if not self.output_stack:
            # Transfer elements from input to output
            while self.input_stack:
                self.output_stack.append(self.input_stack.pop())
        # Return the top of output stack without removing
        if not self.output_stack:
            return -1
        return self.output_stack[-1]

    def empty(self) -> bool:
        # Queue is empty if both stacks are empty
        return not self.input_stack and not self.output_stack

def nextGreaterElements(arr):
    n = len(arr)
    res = [-1] * n
    # Compare each element with elements on its right
    for i in range(n):
        for j in range(i + 1, n):
            if arr[j] > arr[i]:
                res[i] = arr[j]
                break
    return res

def sortStack(stack):
    # Helper list to sort the stack elements
    arr = []
    while stack:
        arr.append(stack.pop())
    # Sort the array
    arr.sort()
    # Push sorted elements back to stack
    for x in arr:
        stack.append(x)

def largestRectangleArea(heights):
    max_area = 0
    n = len(heights)
    # Check every pair of bar boundaries
    for i in range(n):
        min_h = heights[i]
        for j in range(i, n):
            min_h = min(min_h, heights[j])
            max_area = max(max_area, min_h * (j - i + 1))
    return max_area

def orangesRotting(grid):
    rows, cols = len(grid), len(grid[0])
    minutes = 0
    # Repeat until no more oranges can rot
    while True:
        to_rot = []
        fresh_count = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    fresh_count += 1
                    # Check neighbors for rotten orange
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 2:
                            to_rot.append((r, c))
                            break
        if not to_rot:
            return minutes if fresh_count == 0 else -1
        # Rot the oranges
        for r, c in to_rot:
            grid[r][c] = 2
        minutes += 1

