class MinStack:
    def __init__(self):
        # List of tuples: (value, current_min)
        self.stack = []

    def push(self, val: int) -> None:
        # Determine the new minimum
        current_min = val
        if self.stack:
            current_min = min(val, self.stack[-1][1])
        # Append value and minimum tuple
        self.stack.append((val, current_min))

    def pop(self) -> None:
        # Remove top element
        self.stack.pop()

    def top(self) -> int:
        # Return top element value
        return self.stack[-1][0]

    def getMin(self) -> int:
        # Return current minimum
        return self.stack[-1][1]

def reverseWords(s: str) -> str:
    # Step-by-step split and reverse manual implementation
    words = []
    temp = ""
    # Extract words manually
    for char in s:
        if char != " ":
            temp += char
        else:
            if temp:
                words.append(temp)
                temp = ""
    if temp:
        words.append(temp)
    # Reverse the words list
    words.reverse()
    # Join manually
    res = ""
    for i in range(len(words)):
        res += words[i]
        if i != len(words) - 1:
            res += " "
    return res

def longestPalindrome(s: str) -> str:
    # Return empty string if input is empty
    if not s:
        return ""

    n = len(s)
    longest = ""

    # Iterate over all possible starting positions of substrings
    for i in range(n):
        # Iterate over all possible ending positions
        for j in range(i, n):
            substring = s[i:j+1]
            # Check if current substring is equal to its reverse
            if substring == substring[::-1]:
                # If this palindrome is longer than the previous maximum, update it
                if len(substring) > len(longest):
                    longest = substring

    # Return the longest palindromic substring found
    return longest

def romanToInt(s: str) -> int:
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    subtractive = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}
    total = 0
    i = 0
    n = len(s)
    # Process characters from left to right
    while i < n:
        # Check if the next two characters form a subtractive pair
        if i + 1 < n and s[i:i+2] in subtractive:
            # Add subtractive value and advance pointer by 2
            total += subtractive[s[i:i+2]]
            i += 2
        else:
            # Add single character value and advance pointer by 1
            total += roman[s[i]]
            i += 1
    # Return total integer value
    return total

def longestCommonPrefix(strs: list[str]) -> str:
    if not strs:
        return ""

    # Iterate through the indices of the first string
    for i in range(len(strs[0])):
        char = strs[0][i]
        # Compare this character with the same index of all other strings
        for j in range(1, len(strs)):
            # If current string is shorter or has a different character, return current prefix
            if i >= len(strs[j]) or strs[j][i] != char:
                return strs[0][:i]

    # Return the entire first string if no mismatch is found
    return strs[0]

def longestCommonPrefix(strs: list[str]) -> str:
    # If the input list is empty, return empty string
    if not strs:
        return ""

    # Assume the first string is the starting prefix
    prefix = strs[0]

    # Compare the prefix with each string in the list
    for i in range(1, len(strs)):
        # Shrink the prefix until strs[i] starts with the prefix
        while not strs[i].startswith(prefix):
            prefix = prefix[:-1]
            # If prefix becomes empty, return immediately
            if not prefix:
                return ""

    # Return the longest common prefix
    return prefix

def rabinKarp(text: str, pattern: str) -> int:
    n, m = len(text), len(pattern)
    # If pattern is longer than text, it cannot match
    if m > n:
        return -1

    # Check every starting position in the text
    for i in range(n - m + 1):
        # Check if the substring matches the pattern
        if text[i:i+m] == pattern:
            return i

    # Return -1 if not found
    return -1

def zFunction(s: str) -> list[int]:
    n = len(s)
    z = [0] * n

    # Loop through each position from 1 to n-1
    for i in range(1, n):
        # Compare characters starting from i with the prefix
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1

    # Return the computed Z-array
    return z

def kmpSearch(text: str, pattern: str) -> int:
    n, m = len(text), len(pattern)
    if m == 0:
        return 0

    # Iterate through all possible starting positions in text
    for i in range(n - m + 1):
        j = 0
        # Compare pattern with substring of text
        while j < m and text[i + j] == pattern[j]:
            j += 1
        # If full match is found, return the start index
        if j == m:
            return i

    return -1

def kmpSearch(text: str, pattern: str) -> int:
    m = len(pattern)
    n = len(text)
    if m == 0:
        return 0

    # Compute the Longest Prefix Suffix (LPS) array
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    # Search phase using the LPS array
    i = 0  # text index
    j = 0  # pattern index
    while i < n:
        if pattern[j] == text[i]:
            i += 1
            j += 1
        if j == m:
            # Return the matching start index
            return i - j
        elif i < n and pattern[j] != text[i]:
            # Skip redundant comparisons using LPS array
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return -1

def minCharForPalindrome(s: str) -> int:
    if not s:
        return 0

    n = len(s)
    # Check prefixes from longest to shortest
    for i in range(n, 0, -1):
        # Extract prefix of length i
        prefix = s[:i]
        # If prefix is a palindrome, return remaining length
        if prefix == prefix[::-1]:
            return n - i

    return 0

def isAnagram(s: str, t: str) -> bool:
    # If lengths are not equal, they cannot be anagrams
    if len(s) != len(t):
        return False

    # Sort characters of both strings and compare them
    return sorted(s) == sorted(t)

def isAnagram(s: str, t: str) -> bool:
    # Anagrams must have the exact same length
    if len(s) != len(t):
        return False

    # Fixed-size array to store counts of 26 English letters
    count = [0] * 26

    # Iterate through strings and count character frequencies
    for i in range(len(s)):
        count[ord(s[i]) - ord('a')] += 1
        count[ord(t[i]) - ord('a')] -= 1

    # Check if all counts are zero
    for val in count:
        if val != 0:
            return False

    return True

