    for i in range(len(s), 0, -1):
        prefix = s[:i]
        # If the prefix is a palindrome, it is the longest
        if prefix == prefix[::-1]:
            return prefix

    return ""

def strStr(haystack: str, needle: str) -> int:
    # Return 0 if needle is empty
    if not needle:
        return 0

    n, m = len(haystack), len(needle)
    # Slide a window of length m across haystack
    for i in range(n - m + 1):
        if haystack[i:i+m] == needle:
            return i

    return -1

def strStr(haystack: str, needle: str) -> int:
    if not needle:
        return 0

    n = len(haystack)
    m = len(needle)
    lps = [0] * m
    length = 0
    i = 1

    # Step 1: Precompute LPS array for the needle
    while i < m:
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    # Step 2: Search phase
    i = 0  # haystack index
    j = 0  # needle index
    while i < n:
        if needle[j] == haystack[i]:
            i += 1
            j += 1
        if j == m:
            # Match found, return the start index
            return i - j
        elif i < n and needle[j] != haystack[i]:
            # Mismatch. Use LPS table to slide needle
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return -1

def isBalanced(root):
    # Helper function to compute height of a subtree
    def getHeight(node):
        if not node:
            return 0
        return 1 + max(getHeight(node.left), getHeight(node.right))

    # If tree is empty, it is balanced
    if not root:
        return True
    # Calculate heights of left and right subtrees
    left_h = getHeight(root.left)
    right_h = getHeight(root.right)
    # Check if current node is balanced and recurse for children
    if abs(left_h - right_h) > 1:
        return False
    return isBalanced(root.left) and isBalanced(root.right)

def isBalanced(root):
    # Helper function returns height if balanced, else -1
    def check(node):
        # Base case: empty node has height 0
        if not node:
            return 0
        # Get height of left subtree
        left_h = check(node.left)
        # If left subtree is unbalanced, propagate -1 upwards
        if left_h == -1:
            return -1
        # Get height of right subtree
        right_h = check(node.right)
        # If right subtree is unbalanced, propagate -1 upwards
        if right_h == -1:
            return -1
        # If heights differ by more than 1, current subtree is unbalanced
        if abs(left_h - right_h) > 1:
            return -1
        # Return actual height of current node
        return 1 + max(left_h, right_h)

    # Root is balanced if check does not return -1
    return check(root) != -1

def diameterOfBinaryTree(root):
    # Helper to compute height of a subtree
    def height(node):
        if not node:
            return 0
        return 1 + max(height(node.left), height(node.right))

    # Base case: empty node has diameter 0
    if not root:
        return 0
    # Calculate left and right heights
    left_h = height(root.left)
    right_h = height(root.right)
    # Diameter through current root
    curr_diameter = left_h + right_h
    # Recurse on left and right subtrees
    left_diameter = diameterOfBinaryTree(root.left)
    right_diameter = diameterOfBinaryTree(root.right)
    # Return maximum of all diameters
    return max(curr_diameter, left_diameter, right_diameter)

def maxPathSum(root):
    # Helper to compute max branch sum from a node
    def max_branch(node):
        if not node:
            return 0
        # Return maximum branch sum (must be non-negative)
        return max(0, node.val + max(max_branch(node.left), max_branch(node.right)))

    # Base case
    if not root:
        return float('-inf')
    # Calculate max path sum passing through root
    left_contrib = max(0, max_branch(root.left))
    right_contrib = max(0, max_branch(root.right))
    curr_sum = root.val + left_contrib + right_contrib
    # Recurse on children
    left_max = maxPathSum(root.left)
    right_max = maxPathSum(root.right)
    # Return maximum of all
    return max(curr_sum, left_max, right_max)

def isSameTree(p, q):
    # If both nodes are null, trees are identical from here
    if not p and not q:
        return True
    # If one node is null and the other is not, they are not identical
    if not p or not q:
        return False
    # If values of current nodes do not match, they are not identical
    if p.val != q.val:
        return False
    # Recursively check left subtrees and right subtrees
    return isSameTree(p.left, q.left) and isSameTree(p.right, q.right)

def zigzagLevelOrder(root):
    if not root:
        return []
    queue = [root]
    result = []
    while queue:
        level_size = len(queue)
        level_nodes = []
        for _ in range(level_size):
            curr = queue.pop(0)
            level_nodes.append(curr.val)
            if curr.left:
                queue.append(curr.left)
            if curr.right:
                queue.append(curr.right)
        result.append(level_nodes)
    # Reverse odd indexed levels
    for i in range(len(result)):
        if i % 2 == 1:
            result[i].reverse()
    return result

def boundaryTraversal(root):
    if not root:
        return []

    # Check if node is leaf
    def isLeaf(node):
        return not node.left and not node.right

    # Collect left boundary
    def getLeftBoundary(node, res):
        curr = node
        while curr:
            if not isLeaf(curr):
                res.append(curr.val)
            curr = curr.left if curr.left else curr.right

    # Collect leaf nodes
    def getLeaves(node, res):
        if not node:
            return
        if isLeaf(node):
            res.append(node.val)
            return
        getLeaves(node.left, res)
        getLeaves(node.right, res)

    # Collect right boundary (to be reversed)
    def getRightBoundary(node, res):
        curr = node
        temp = []
        while curr:
            if not isLeaf(curr):
                temp.append(curr.val)
            curr = curr.right if curr.right else curr.left
        res.extend(reversed(temp))

    res = []
    if not isLeaf(root):
        res.append(root.val)
    getLeftBoundary(root.left, res)
    getLeaves(root, res)
    getRightBoundary(root.right, res)
    return res

def topView(root):
    col_map = {}
    # DFS traversal
    def dfs(node, row, col):
        if not node:
            return
        # If col not seen, or seen but at a lower depth (row)
        if col not in col_map or row < col_map[col][0]:
            col_map[col] = (row, node.val)
        dfs(node.left, row + 1, col - 1)
        dfs(node.right, row + 1, col + 1)

    dfs(root, 0, 0)
    # Sort columns and extract values
    return [col_map[c][1] for c in sorted(col_map.keys())]

def bottomView(root):
    col_map = {}
    # DFS traversal
    def dfs(node, row, col):
        if not node:
            return
        # Store or overwrite if row is greater or equal
        if col not in col_map or row >= col_map[col][0]:
            col_map[col] = (row, node.val)
        dfs(node.left, row + 1, col - 1)
        dfs(node.right, row + 1, col + 1)

    dfs(root, 0, 0)
    return [col_map[c][1] for c in sorted(col_map.keys())]

def rightSideView(root):
    if not root:
        return []
    queue = [root]
    result = []
    while queue:
        level_size = len(queue)
        for i in range(level_size):
            curr = queue.pop(0)
            # If it is the last element of the level, add to result
            if i == level_size - 1:
                result.append(curr.val)
            if curr.left:
                queue.append(curr.left)
            if curr.right:
                queue.append(curr.right)
    return result

def leftSideView(root):
    if not root:
        return []
    queue = [root]
    result = []
    while queue:
        level_size = len(queue)
        for i in range(level_size):
            curr = queue.pop(0)
            # If it is the first element of the level, add to result
            if i == 0:
                result.append(curr.val)
            if curr.left:
                queue.append(curr.left)
            if curr.right:
                queue.append(curr.right)
    return result

def isSymmetric(root):
    # Helper to clone and mirror the tree
    def cloneAndMirror(node):
        if not node:
            return None
        new_node = TreeNode(node.val)
        new_node.left = cloneAndMirror(node.right)
        new_node.right = cloneAndMirror(node.left)
        return new_node

    # Helper to check if two trees are identical
    def isIdentical(p, q):
        if not p and not q:
            return True
        if not p or not q:
            return False
        return p.val == q.val and isIdentical(p.left, q.left) and isIdentical(p.right, q.right)

    if not root:
        return True
    mirrored_root = cloneAndMirror(root)
    return isIdentical(root, mirrored_root)

def isSymmetric(root):
    # Helper function to check if two subtrees are mirrors of each other
    def isMirror(t1, t2):
        # If both subtrees are null, they are symmetric
        if not t1 and not t2:
            return True
        # If only one is null, they are not symmetric
        if not t1 or not t2:
            return False
        # Check if current values match and their subtrees are mirrored
        return (t1.val == t2.val and 
                isMirror(t1.left, t2.right) and 
                isMirror(t1.right, t2.left))

    # If root is null, it is symmetric
    if not root:
        return True
    # Check if left and right subtrees are mirrors of each other
    return isMirror(root.left, root.right)

def solve(root, target):
    all_paths = []
    # DFS to find all paths
    def dfs(node, path):
        if not node:
            return
        curr_path = path + [node.val]
        all_paths.append(curr_path)
        dfs(node.left, curr_path)
        dfs(node.right, curr_path)

    dfs(root, [])
    # Search for path ending with target
    for p in all_paths:
        if p[-1] == target:
            return p
    return []

def lowestCommonAncestor(root, p, q):
    # Find paths for p and q
    def get_path(node, target, path):
        if not node:
            return False
        path.append(node)
        if node == target:
            return True
        if get_path(node.left, target, path) or get_path(node.right, target, path):
            return True
        path.pop()
        return False

    path_p, path_q = [], []
    get_path(root, p, path_p)
    get_path(root, q, path_q)

    # Compare paths to find LCA
    lca = None
    for node_p, node_q in zip(path_p, path_q):
        if node_p == node_q:
            lca = node_p
        else:
            break
    return lca

def isParentSum(root):
    # Base case: empty node satisfies property
    if not root:
        return True
    # Base case: leaf node satisfies property
    if not root.left and not root.right:
        return True
    # Sum of children
    child_sum = 0
    if root.left:
        child_sum += root.left.val
    if root.right:
        child_sum += root.right.val
    # Check current node and recursively check children
    return root.val == child_sum and isParentSum(root.left) and isParentSum(root.right)

def changeTree(root):
    # Base case: if root is None, return
    if not root:
        return
    # Base case: if it is a leaf node, return
    if not root.left and not root.right:
        return
    # Calculate sum of children
    child_sum = 0
    if root.left:
        child_sum += root.left.val
    if root.right:
        child_sum += root.right.val
    # If parent's value is greater than sum of children
    if root.val > child_sum:
        if root.left:
            root.left.val = root.val
        if root.right:
            root.right.val = root.val
    # Recurse on left and right subtrees
    changeTree(root.left)
    changeTree(root.right)
    # Post-order update of parent value
    tot_sum = 0
    if root.left:
        tot_sum += root.left.val
    if root.right:
        tot_sum += root.right.val
    # Update parent value
    root.val = tot_sum

def distanceK(root, target, k):
    from collections import defaultdict
    # Adjacency list representation of the tree as a graph
    graph = defaultdict(list)
    # DFS helper to build graph edges
    def build_graph(node, parent):
        if not node:
            return
        if parent:
            graph[node.val].append(parent.val)
            graph[parent.val].append(node.val)
        build_graph(node.left, node)
        build_graph(node.right, node)
    # Build graph starting from root
    build_graph(root, None)
    # BFS initialization
    queue = [target.val]
    visited = {target.val}
    curr_dist = 0
    # BFS up to distance k
    while queue:
        if curr_dist == k:
            return queue
        next_queue = []
        for node_val in queue:
            for neighbor in graph[node_val]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_queue.append(neighbor)
        queue = next_queue
        curr_dist += 1
    # Return empty list if target distance cannot be reached
    return []

def countNodes(root):
    # Base case: if root is None, return 0
    if not root:
        return 0
    # Count 1 for the root, plus recursive count of left and right subtrees
    return 1 + countNodes(root.left) + countNodes(root.right)

def countNodes(root):
    # If root is None, return 0
    if not root:
        return 0
    # Helper to calculate left height
    def get_left_height(node):
        h = 0
        while node:
            h += 1
            node = node.left
        return h
    # Helper to calculate right height
    def get_right_height(node):
        h = 0
        while node:
            h += 1
            node = node.right
        return h
    # Calculate heights
    lh = get_left_height(root)
    rh = get_right_height(root)
    # If left height equals right height, it is a perfect binary tree
    if lh == rh:
        return (1 << lh) - 1
    # Otherwise, recursively count nodes in left and right subtrees
    return 1 + countNodes(root.left) + countNodes(root.right)

def serialize(root):
    # Helper to calculate height of tree
    def get_height(node):
        if not node: return 0
        return 1 + max(get_height(node.left), get_height(node.right))
    h = get_height(root)
    # Total slots needed for a full binary tree
    total_size = (1 << h) - 1
    arr = ["#"] * total_size
    # Helper to place nodes in array
    def fill(node, i):
        if not node: return
        arr[i] = str(node.val)
        fill(node.left, 2 * i + 1)
        fill(node.right, 2 * i + 2)
    fill(root, 0)
    return ",".join(arr)

def deserialize(data):
    if not data:
        return None
    arr = data.split(",")
    nodes = [None if val == "#" else TreeNode(int(val)) for val in arr]
    for i in range(len(nodes)):
        if nodes[i]:
            left_idx = 2 * i + 1
            right_idx = 2 * i + 2
            if left_idx < len(nodes):
                nodes[i].left = nodes[left_idx]
            if right_idx < len(nodes):
                nodes[i].right = nodes[right_idx]
    return nodes[0] if nodes else None

def insertIntoBST(root, val):
    # If root is None, return new node
    if not root:
        return TreeNode(val)
    # Recurse on left or right subtree
    if val < root.val:
        root.left = insertIntoBST(root.left, val)
    else:
        root.right = insertIntoBST(root.right, val)
    # Return root
    return root

def insertIntoBST(root, val):
    # If root is None, return new node
    if not root:
        return TreeNode(val)
    # Pointer to traverse the BST
    curr = root
    # Loop to find the insertion point
    while True:
        # If value is smaller than current node
        if val < curr.val:
            # If left child exists, move left
            if curr.left:
                curr = curr.left
            # If left child is None, insert here
            else:
                curr.left = TreeNode(val)
                break
        # If value is larger than current node
        else:
            # If right child exists, move right
            if curr.right:
                curr = curr.right
            # If right child is None, insert here
            else:
                curr.right = TreeNode(val)
                break
    # Return the root of BST
    return root

def knapsack(W: int, wt: list[int], val: list[int]) -> int:
    n = len(wt)
    # Define recursive helper function
    def helper(idx, rem_w):
        # Base Case: no items left or knapsack is full
        if idx == n or rem_w == 0:
            # Return 0 value
            return 0
        # If weight of current item exceeds remaining capacity, skip it
        if wt[idx] > rem_w:
            return helper(idx + 1, rem_w)
        # Case 1: Pick the current item
        take = val[idx] + helper(idx + 1, rem_w - wt[idx])
        # Case 2: Skip the current item
        skip = helper(idx + 1, rem_w)
        # Return the maximum of both choices
        return max(take, skip)
    # Start search from index 0
    return helper(0, W)

def unboundedKnapsack(W: int, wt: list[int], val: list[int]) -> int:
    n = len(wt)
    # Recursive helper function
    def helper(rem_w):
        # Base Case: if remaining weight is 0 or less, value is 0
        if rem_w <= 0:
            return 0
        max_val = 0
        # Check every item for inclusion
        for i in range(n):
            # If item weight fits in remaining capacity
            if wt[i] <= rem_w:
                # Update max_val by including this item
                max_val = max(max_val, val[i] + helper(rem_w - wt[i]))
        # Return maximum value possible with capacity rem_w
        return max_val
    # Call helper with full capacity
    return helper(W)

def unboundedKnapsack(W: int, wt: list[int], val: list[int]) -> int:
    n = len(wt)
    # Initialize dp array of size W + 1 with 0s
    dp = [0] * (W + 1)
    # Compute max value for every capacity from 1 to W
    for w in range(1, W + 1):
        # Check each item to see if it can fit in current capacity w
        for i in range(n):
            if wt[i] <= w:
                # Update DP table with the best value
                dp[w] = max(dp[w], dp[w - wt[i]] + val[i])
    # Return the maximum value for capacity W
    return dp[W]

def cutRod(price: list[int], n: int) -> int:
    # Helper recursive function
    def helper(rem_len):
        # Base Case: if remaining length is 0, no price
        if rem_len == 0:
            return 0
        max_val = 0
        # Try cutting at every possible length from 1 to rem_len
        for i in range(1, rem_len + 1):
            # Update max_val with best cut
            max_val = max(max_val, price[i - 1] + helper(rem_len - i))
        return max_val
    # Call helper with initial length n
    return helper(n)

def longestCommonSubsequence(text1: str, text2: str) -> int:
    # Recursive helper with indices i and j
    def helper(i, j):
        # Base Case: if we reach end of either string, length is 0
        if i == len(text1) or j == len(text2):
            return 0
        # If characters match, increment length and move both pointers
        if text1[i] == text2[j]:
            return 1 + helper(i + 1, j + 1)
        # Else, try moving each pointer and take the max
        return max(helper(i + 1, j), helper(i, j + 1))
    # Start recursion at (0, 0)
    return helper(0, 0)

def longestCommonSubsequence(text1: str, text2: str) -> int:
    m, n = len(text1), len(text2)
    # Create a 2D table of size (m+1) x (n+1) initialized with 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Iterate backwards through both strings
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            # If characters match, take diagonal value and add 1
            if text1[i] == text2[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                # Else, take maximum of moving right or down in the table
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
    # Return top-left value containing the answer
    return dp[0][0]

def longestCommonSubstring(S1: str, S2: str) -> int:
    n, m = len(S1), len(S2)
    max_len = 0
    # Generate all starting indices of S1
    for i in range(n):
        # Generate all ending indices of S1
        for j in range(i + 1, n + 1):
            substring = S1[i:j]
            # Check if this substring exists in S2
            if substring in S2:
                # Update max_len if this substring is longer
                max_len = max(max_len, len(substring))
    return max_len

def longestPalindromeSubseq(s: str) -> int:
    # Recursive helper with left index i and right index j
    def helper(i, j):
        # Base Case: empty substring
        if i > j:
            return 0
        # Base Case: single character substring is always a palindrome
        if i == j:
            return 1
        # If boundary characters match, add 2 and move inwards
        if s[i] == s[j]:
            return 2 + helper(i + 1, j - 1)
        # Otherwise, try skipping left character or right character
        return max(helper(i + 1, j), helper(i, j - 1))
    # Start search from the full string boundaries
    return helper(0, len(s) - 1)

def minDistance(word1: str, word2: str) -> int:
    # Recursive helper with lengths i and j
    def helper(i, j):
        # If word1 is exhausted, we need to insert all word2 chars
        if i == 0:
            return j
        # If word2 is exhausted, we need to delete all word1 chars
        if j == 0:
            return i
        # If characters match, no operation needed
        if word1[i - 1] == word2[j - 1]:
            return helper(i - 1, j - 1)
        # Else try insert, delete, replace and take min
        return 1 + min(
            helper(i, j - 1),    # Insert
            helper(i - 1, j),    # Delete
            helper(i - 1, j - 1) # Replace
        )
    return helper(len(word1), len(word2))

def minDistance(word1: str, word2: str) -> int:
    m, n = len(word1), len(word2)
    # Initialize 2D DP array with size (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Base cases: converting string of length i to empty string requires i deletions
    for i in range(m + 1):
        dp[i][0] = i
    # Base cases: converting empty string to string of length j requires j insertions
    for j in range(n + 1):
        dp[0][j] = j
    # Populate DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # If characters match, no operation cost is added
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                # Min of insert, delete, replace + 1
                dp[i][j] = 1 + min(
                    dp[i][j - 1],    # Insert
                    dp[i - 1][j],    # Delete
                    dp[i - 1][j - 1] # Replace
                )
    # Return the edit distance at bottom-right cell
    return dp[m][n]

def numDistinct(s: str, t: str) -> int:
    # Helper recursive function
    def helper(i, j):
        # Base Case: all of t is matched
        if j == len(t):
            return 1
        # Base Case: s is exhausted but t is not
        if i == len(s):
            return 0
        # If characters match, try both matching this char and skipping it
        if s[i] == t[j]:
            return helper(i + 1, j + 1) + helper(i + 1, j)
        # Else, skip this character of s
        return helper(i + 1, j)
    return helper(0, 0)

def isMatch(s: str, p: str) -> bool:
    # Helper recursive function
    def helper(i, j):
        # Base Case: if pattern is fully consumed, check if string is too
        if j == len(p):
            return i == len(s)
        # If string is fully consumed, pattern must only have '*' left
        if i == len(s):
            return p[j] == '*' and helper(i, j + 1)
        # If wildcard '*', we can choose to match 0 or >=1 character
        if p[j] == '*':
            return helper(i + 1, j) or helper(i, j + 1)
        # If characters match or '?', proceed to next
        if p[j] == '?' or s[i] == p[j]:
            return helper(i + 1, j + 1)
        return False
    return helper(0, 0)

def lengthOfLIS(nums: list[int]) -> int:
    # Helper recursive function
    def helper(idx, prev_idx):
        # Base Case: reached end of array
        if idx == len(nums):
            return 0
        # Choice 1: Skip current element
        skip = helper(idx + 1, prev_idx)
        take = 0
        # Choice 2: Take current element if it's greater than previous selection
        if prev_idx == -1 or nums[idx] > nums[prev_idx]:
            take = 1 + helper(idx + 1, idx)
        # Return maximum of both paths
        return max(skip, take)
    return helper(0, -1)

def lengthOfLIS(nums: list[int]) -> int:
    # sub will store the smallest tail values of increasing subsequences
    sub = []
    # Iterate through all numbers in nums
    for num in nums:
        # Binary search manually for insertion index
        left, right = 0, len(sub)
        while left < right:
            mid = (left + right) // 2
            # If mid element is less than num, search right half
            if sub[mid] < num:
                left = mid + 1
            else:
                # Else search left half
                right = mid
        # If num is larger than all elements in sub, append it
        if left == len(sub):
            sub.append(num)
        else:
            # Otherwise, replace the first element that is >= num
            sub[left] = num
    # Length of sub represents the length of LIS
    return len(sub)

def longestStrChain(words: list[str]) -> int:
    # Helper to check if w1 is predecessor of w2
    def isPredecessor(w1, w2):
        if len(w2) != len(w1) + 1:
            return False
        i, j = 0, 0
        while i < len(w1) and j < len(w2):
            if w1[i] == w2[j]:
                i += 1
            j += 1
        return i == len(w1)

    # Sort words by length
    words.sort(key=len)
    n = len(words)
    # Recursive helper
    def helper(idx):
        max_len = 1
        for i in range(idx + 1, n):
            if isPredecessor(words[idx], words[i]):
                max_len = max(max_len, 1 + helper(i))
        return max_len

    ans = 0
    for i in range(n):
        ans = max(ans, helper(i))
    return ans

def LongestBitonicSequence(nums: list[int]) -> int:
    n = len(nums)
    # Recursive LIS helper
    def get_lis(idx, prev_idx):
        if idx < 0:
            return 0
        skip = get_lis(idx - 1, prev_idx)
        take = 0
        if prev_idx == -1 or nums[idx] < nums[prev_idx]:
            take = 1 + get_lis(idx - 1, idx)
        return max(skip, take)

    # Recursive LDS helper
    def get_lds(idx, prev_idx):
        if idx == n:
            return 0
        skip = get_lds(idx + 1, prev_idx)
        take = 0
        if prev_idx == -1 or nums[idx] < nums[prev_idx]:
            take = 1 + get_lds(idx + 1, idx)
        return max(skip, take)

    max_len = 0
    # Try each element as the peak of the bitonic sequence
    for i in range(n):
        # LIS ending at i is get_lis(i, -1), LDS starting at i is get_lds(i, -1)
        # Peak is counted twice, so subtract 1
        max_len = max(max_len, get_lis(i, -1) + get_lds(i, -1) - 1)
    return max_len

def LongestBitonicSequence(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    # lis[i] stores the length of LIS ending at index i
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # lds[i] stores the length of LDS starting at index i
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum value of (lis[i] + lds[i] - 1)
    max_len = 0
    for i in range(n):
        max_len = max(max_len, lis[i] + lds[i] - 1)
    # Return the maximum bitonic sequence length
    return max_len

def matrixMultiplication(arr: list[int]) -> int:
    # Recursive helper function
    def helper(i, j):
        # Base Case: single matrix has 0 multiplication cost
        if i == j:
            return 0
        min_cost = float('inf')
        # Try all split points k between i and j-1
        for k in range(i, j):
            # Cost = left chain cost + right chain cost + multiplication cost of results
            cost = helper(i, k) + helper(k + 1, j) + arr[i - 1] * arr[k] * arr[j]
            min_cost = min(min_cost, cost)
        return min_cost
    # Call helper with first matrix index 1 and last matrix index N-1
    return helper(1, len(arr) - 1)

def maxProfit(prices: List[int]) -> int:
    n = len(prices)  # total number of days
    best = 0  # best profit seen so far (0 = never trade)
    # Try every possible buy day
    for buy in range(n):
        # Pair it with every strictly later sell day
        for sell in range(buy + 1, n):
            # Profit if we buy on 'buy' and sell on 'sell'
            profit = prices[sell] - prices[buy]
            # Keep this pair only if it beats the current best
            if profit > best:
                best = profit
    return best  # maximum profit over all valid (buy, sell) pairs

def rotate(matrix: List[List[int]]) -> None:
    n = len(matrix)  # square size
    # Build a brand-new rotated matrix (costs O(n^2) extra space)
    rotated = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # Rule: value at (i, j) lands at (j, n-1-i) after a CW turn
            rotated[j][n - 1 - i] = matrix[i][j]
    # Copy the answer back so the caller sees an in-place change
    for i in range(n):
        for j in range(n):
            matrix[i][j] = rotated[i][j]  # overwrite cell by cell

def rotate(matrix: List[List[int]]) -> None:
    n = len(matrix)  # the matrix is n x n
    # Step 1: transpose — mirror every cell across the main diagonal
    for i in range(n):
        # j starts at i + 1 so each pair (i,j)/(j,i) swaps exactly once
        for j in range(i + 1, n):
            # Swap the cell with its mirror across the diagonal
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # Step 2: reverse every row to finish the 90-degree clockwise turn
    for row in matrix:
        # In-place left-right flip of one row
        row.reverse()

def merge(intervals: List[List[int]]) -> List[List[int]]:
    intervals = sorted(intervals)  # sort by start so overlap candidates sit together
    n = len(intervals)  # total interval count
    ans = []  # finished, disjoint blocks
    for i in range(n):
        start, end = intervals[i]  # seed a candidate block from interval i
        # Already swallowed by the last sealed block? Then skip this seed.
        if ans and end <= ans[-1][1]:
            continue
        # Re-scan every later interval and absorb all that touch [start, end]
        for j in range(i + 1, n):
            if intervals[j][0] <= end:
                end = max(end, intervals[j][1])  # extend the right edge
        ans.append([start, end])  # seal the fully-grown block
    return ans  # disjoint intervals covering the same points

def merge(nums1: List[int], m: int, nums2: List[int], n: int) -> None:
    # Copy every nums2 element into the spare zero slots at nums1's tail
    for j in range(n):
        nums1[m + j] = nums2[j]  # slot m+j is guaranteed to be free
    # nums1 now holds all m+n values, just unordered — sorting fixes that
    nums1.sort()  # Timsort: O((m+n) log (m+n)) time

def findDuplicate(nums: List[int]) -> int:
    n = len(nums)  # n+1 numbers with values in 1..n
    # Compare every pair of positions — the definition of "duplicate"
    for i in range(n):
        for j in range(i + 1, n):
            # Same value at two different indices = the repeated number
            if nums[i] == nums[j]:
                return nums[i]
    return -1  # unreachable: a duplicate is guaranteed to exist

def findDuplicate(nums: List[int]) -> int:
    seen = set()  # values met so far; O(1) average membership test
    for x in nums:
        # If x was already met at an earlier index, it is the duplicate
        if x in seen:
            return x
        seen.add(x)  # first sighting of x: remember it
    return -1  # unreachable: a duplicate is guaranteed

def findRepeatMissing(nums: List[int]) -> List[int]:
    n = len(nums)  # values are supposed to be 1..n
    repeat, missing = -1, -1  # placeholders until each is found
    # For every value v that SHOULD appear, count how often it really does
    for v in range(1, n + 1):
        count = 0  # occurrences of v in the array
        for x in nums:
            if x == v:
                count += 1  # one more sighting of v
        if count == 2:
            repeat = v   # v appears twice -> it is the repeated number
        elif count == 0:
            missing = v  # v never appears -> it is the missing number
    return [repeat, missing]

def findRepeatMissing(nums: List[int]) -> List[int]:
    n = len(nums)  # values should cover 1..n
    count = [0] * (n + 1)  # count[v] = occurrences of value v (slot 0 unused)
    # Pass 1: tally every array value in O(1) each
    for x in nums:
        count[x] += 1  # one more occurrence of x
    repeat, missing = -1, -1  # to be discovered in the tally
    # Pass 2: read the tally — 2 means repeated, 0 means missing
    for v in range(1, n + 1):
        if count[v] == 2:
            repeat = v   # seen twice
        elif count[v] == 0:
            missing = v  # never seen
    return [repeat, missing]

def inversionCount(arr: List[int]) -> int:
    n = len(arr)  # number of elements
    count = 0  # running inversion total
    # Check every pair (i, j) with i < j — the literal definition
    for i in range(n):
        for j in range(i + 1, n):
            # Inversion: earlier element strictly bigger than a later one
            if arr[i] > arr[j]:
                count += 1  # found one out-of-order pair
    return count  # total number of inversions

def searchMatrix(matrix: List[List[int]], target: int) -> bool:
    # Look at every cell, ignoring the sorted structure entirely
    for row in matrix:
        for val in row:
            # Direct comparison against the target
            if val == target:
                return True  # found a match — stop immediately
    return False  # scanned all m*n cells without a hit

def searchMatrix(matrix: List[List[int]], target: int) -> bool:
    m, n = len(matrix), len(matrix[0])  # dimensions
    r, c = 0, n - 1  # start at the TOP-RIGHT corner
    # Corner property: left neighbours are smaller, lower neighbours bigger
    while r < m and c >= 0:
        val = matrix[r][c]  # current corner of the surviving sub-matrix
        if val == target:
            return True  # found it
        elif val > target:
            c -= 1  # whole column below is even bigger — discard it, step left
        else:
            r += 1  # whole row to the left is even smaller — discard it, step down
    return False  # walked off the matrix: the target cannot exist

def searchMatrix(matrix: List[List[int]], target: int) -> bool:
    m, n = len(matrix), len(matrix[0])  # rows, cols
    # Key insight: read row-by-row, the whole matrix is ONE sorted
    # list of m*n values — so run a single binary search on it.
    lo, hi = 0, m * n - 1  # virtual 1-D search window
    while lo <= hi:
        mid = (lo + hi) // 2  # middle virtual index
        # Un-flatten: virtual index -> real cell (row = mid // n, col = mid % n)
        val = matrix[mid // n][mid % n]
        if val == target:
            return True  # found the target
        elif val < target:
            lo = mid + 1  # target can only live in the right half
        else:
            hi = mid - 1  # target can only live in the left half
    return False  # window emptied without ever hitting the target

def is_valid_bst(root):
    # For EVERY node, re-scan its ENTIRE left subtree (all values must be
    # smaller) and its ENTIRE right subtree (all values must be larger).

    def subtree_ok(node, check):
        # True only if EVERY value in this subtree passes 'check'.
        if node is None:
            return True                     # an empty subtree has no violators
        if not check(node.val):
            return False                    # this value breaks the ancestor's rule
        # both children's subtrees must also fully satisfy the rule
        return subtree_ok(node.left, check) and subtree_ok(node.right, check)

    def valid(node):
        if node is None:
            return True                     # an empty tree is a valid BST
        # rule 1: everything on the left is strictly smaller than node.val
        if not subtree_ok(node.left, lambda v: v < node.val):
            return False
        # rule 2: everything on the right is strictly larger than node.val
        if not subtree_ok(node.right, lambda v: v > node.val):
            return False
        # rule 3: both subtrees must themselves be valid BSTs
        return valid(node.left) and valid(node.right)

    return valid(root)                      # start the check at the root

def lowest_common_ancestor(root, p, q):
    # BST insight: walking down from the root, the FIRST node where p and q
    # split apart (one on each side, or equal to it) is their LCA.
    node = root                       # begin the descent at the root
    while node:                       # one root-to-LCA walk, no backtracking
        if p < node.val and q < node.val:
            node = node.left          # both targets live in the left subtree
        elif p > node.val and q > node.val:
            node = node.right         # both targets live in the right subtree
        else:
            return node               # they straddle (or one equals) => LCA
    return None                       # empty tree: nothing to return

def bst_from_preorder(preorder):
    # Preorder visits the root FIRST, so inserting the values one-by-one
    # with the standard BST insert recreates exactly the original tree.

    def insert(node, val):
        # Standard BST insert: walk down and attach a new leaf in place.
        if node is None:
            return TreeNode(val)            # found the empty slot: create the node
        if val < node.val:
            node.left = insert(node.left, val)    # smaller values go left
        else:
            node.right = insert(node.right, val)  # larger values go right
        return node                         # hand back the (unchanged) subtree root

    root = None                             # start from an empty tree
    for val in preorder:                    # n inserts in preorder order
        root = insert(root, val)            # each insert costs O(h) — up to O(n)
    return root                             # sorted input => skewed tree => O(n^2) total

class BSTIterator:
    # Eager approach: do ALL the work up front — flatten the whole tree.
    def __init__(self, root: Optional[TreeNode]):
        self.vals = []           # will hold every value, in sorted order
        self.idx = -1            # index of the value we handed out last
        self._inorder(root)      # one full traversal fills self.vals

    def _inorder(self, node):
        if not node:
            return               # empty subtree contributes nothing
        self._inorder(node.left)     # smaller values first (left subtree)
        self.vals.append(node.val)   # then the node itself
        self._inorder(node.right)    # larger values last (right subtree)

    def next(self) -> int:
        self.idx += 1                # advance to the next stored value
        return self.vals[self.idx]   # O(1) list read

    def hasNext(self) -> bool:
        return self.idx + 1 < len(self.vals)  # True while values remain

class BSTIterator:
    # Lazy inorder: keep ONLY the pending left spine on a stack, not the whole tree.
    def __init__(self, root: Optional[TreeNode]):
        self.stack = []        # nodes whose values are still owed to the caller
        self._push_left(root)  # stage the path down to the smallest value

    def _push_left(self, node):
        # Dive down the left edge, stacking every node we pass.
        while node:
            self.stack.append(node)  # this node's value comes before its right subtree
            node = node.left         # smaller values live down-left

    def next(self) -> int:
        node = self.stack.pop()      # top of the stack IS the next smallest value
        self._push_left(node.right)  # values just after it live in its right subtree
        return node.val              # emit values in sorted order

    def hasNext(self) -> bool:
        return len(self.stack) > 0   # values remain while the stack is non-empty

def findTarget(root: Optional[TreeNode], k: int) -> bool:
    vals = []                        # every value in the tree, any order
    def collect(node):
        if not node:
            return                   # empty subtree: nothing to record
        vals.append(node.val)        # record this node's value
        collect(node.left)           # gather the whole left side
        collect(node.right)          # gather the whole right side
    collect(root)                    # vals now holds all n values
    n = len(vals)
    # Try every unordered pair (i, j) of two DIFFERENT nodes
    for i in range(n):
        for j in range(i + 1, n):    # j > i guarantees two distinct nodes
            if vals[i] + vals[j] == k:
                return True          # found a pair summing to k
    return False                     # no pair of distinct nodes works

def findTarget(root: Optional[TreeNode], k: int) -> bool:
    seen = set()                     # values of all nodes visited so far
    def dfs(node):
        if not node:
            return False             # an empty subtree cannot complete a pair
        if k - node.val in seen:     # a previously seen node is the exact partner
            return True
        seen.add(node.val)           # remember this value for future nodes
        # The partner may live in either subtree — search both
        return dfs(node.left) or dfs(node.right)
    return dfs(root)                 # one pass over the tree decides it

def findTarget(root: Optional[TreeNode], k: int) -> bool:
    arr = []                     # inorder traversal of a BST comes out SORTED
    def inorder(node):
        if not node:
            return               # base case: an empty subtree adds nothing
        inorder(node.left)       # smaller values first
        arr.append(node.val)     # then this node's value
        inorder(node.right)      # larger values last
    inorder(root)                # after this call, arr is sorted ascending
    lo, hi = 0, len(arr) - 1     # two pointers at the two extremes
    while lo < hi:               # need two DIFFERENT nodes, so stop when they meet
        s = arr[lo] + arr[hi]    # candidate pair sum
        if s == k:
            return True          # exact pair found
        if s < k:
            lo += 1              # sum too small -> take a bigger left value
        else:
            hi -= 1              # sum too big -> take a smaller right value
    return False                 # pointers met without a match: no such pair

def largestBst(root: Optional[TreeNode]) -> int:
    # Is the subtree at node a BST whose values all lie strictly in (low, high)?
    def is_bst(node, low, high):
        if not node:
            return True                      # an empty tree is a valid BST
        if not (low < node.val < high):
            return False                     # value violates an ancestor's range
        # Left values must stay below node.val, right values above it
        return is_bst(node.left, low, node.val) and is_bst(node.right, node.val, high)

    def count(node):
        if not node:
            return 0                         # empty subtree has zero nodes
        return 1 + count(node.left) + count(node.right)  # node plus both sides

    def solve(node):
        if not node:
            return 0                         # nothing here to measure
        if is_bst(node, float('-inf'), float('inf')):
            return count(node)               # whole subtree valid -> its size wins here
        # Otherwise the best BST lives strictly inside one of the children
        return max(solve(node.left), solve(node.right))

    return solve(root)                       # best size over every subtree

def isCycle(V, adj):
    # Backtracking search: try to close a loop around each "anchor" vertex
    def explore(start, node, on_path, edges_used):
        # Walk every edge leaving the current end of the path
        for nei in adj[node]:
            # Stepping back onto the anchor after >= 3 edges closes a REAL
            # cycle (2 edges would just be the same edge walked both ways)
            if nei == start and edges_used + 1 >= 3:
                return True
            # Extend the simple path only with vertices not already on it
            if nei not in on_path:
                on_path.add(nei)                    # take the step
                if explore(start, nei, on_path, edges_used + 1):
                    return True                     # a cycle closed deeper down
                on_path.remove(nei)                 # backtrack: undo the step
        # No extension of this particular path loops back to the anchor
        return False

    for s in range(V):
        # A fresh path {s} for every possible anchor vertex
        if explore(s, s, {s}, 0):
            return True
    # No anchor vertex lies on any loop of length >= 3
    return False

def isCycle(V, adj):
    # visited[u] is True once DFS has discovered vertex u
    visited = [False] * V

    def dfs(node, parent):
        # Discover the current vertex
        visited[node] = True
        # Walk every edge leaving node
        for nei in adj[node]:
            if not visited[nei]:
                # Tree edge: dive deeper; bubble a found cycle straight up
                if dfs(nei, node):
                    return True
            elif nei != parent:
                # Already-visited neighbour that is NOT the vertex we came
                # from: we found a second route to nei, i.e. a cycle
                return True
        # No cycle anywhere in the subtree hanging below node
        return False

    # The graph may be disconnected — start a DFS in every fresh component
    for s in range(V):
        if not visited[s]:
            # -1 is a sentinel parent: the root of a DFS tree has no parent
            if dfs(s, -1):
                return True
    # All components searched, no back edge found anywhere
    return False

def isCyclic(V, adj):
    # Colours: 0 = white (untouched), 1 = grey (on the CURRENT recursion
    # path), 2 = black (fully processed — provably leads to no cycle)
    color = [0] * V

    def dfs(u):
        # Entering u puts it on the active recursion path
        color[u] = 1
        for v in adj[u]:
            # A grey neighbour is an ancestor still on our path: back edge!
            if color[v] == 1:
                return True
            # Recurse only into white vertices; black ones are already safe
            if color[v] == 0 and dfs(v):
                return True
        # Leaving u: nothing below it loops back, mark it safe forever
        color[u] = 2
        return False

    # The graph may be disconnected — try every still-white vertex as a root
    for s in range(V):
        if color[s] == 0 and dfs(s):
            return True
    # No back edge found anywhere in any component
    return False

def floyd_warshall(mat):
    # n vertices; mat[i][j] == 10^8 is the sentinel for "no direct edge"
    n = len(mat)
    INF = 10**8
    # Collect the real directed edges once as (u, v, weight) triples
    edges = []
    for u in range(n):
        for v in range(n):
            # skip missing edges and the diagonal (u -> u is always 0)
            if u != v and mat[u][v] != INF:
                edges.append((u, v, mat[u][v]))
    # Run one full Bellman-Ford from EVERY possible source vertex
    answer = []
    for src in range(n):
        dist = [INF] * n            # best-known cost from src to each vertex
        dist[src] = 0               # reaching yourself is free
        # n-1 relaxation passes finalise every shortest path from src
        for _ in range(n - 1):
            for u, v, w in edges:   # try to improve v by going through u
                if dist[u] != INF and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w   # cheaper route found
        answer.append(dist)         # one finished row of the answer
    # The problem wants the matrix updated IN PLACE, so copy rows back
    for i in range(n):
        for j in range(n):
            mat[i][j] = answer[i][j]    # overwrite with the shortest cost
    return mat                      # also return it, for convenience

def spanning_tree(V, edges):
    # Kruskal core idea: always try the cheapest remaining edge first
    order = sorted(edges, key=lambda e: e[2])   # sort by weight
    # comp[v] = id of the connected component v belongs to right now;
    # initially every vertex sits alone in its own component
    comp = list(range(V))
    total = 0                       # running MST weight
    used = 0                        # number of edges accepted so far
    for u, v, w in order:
        if comp[u] == comp[v]:
            continue                # same component: edge would close a cycle
        total += w                  # different components: accept the edge
        used += 1
        old, new = comp[v], comp[u]     # merge v's component into u's
        # naive merge: relabel EVERY vertex that carries v's old id
        for x in range(V):
            if comp[x] == old:
                comp[x] = new       # x now belongs to the merged component
        if used == V - 1:
            break                   # a spanning tree has exactly V-1 edges
    return total                    # sum of the MST edge weights

def maxSumNonAdjacent(nums: List[int]) -> int:
    # solve(i) = best non-adjacent sum achievable using ONLY indices 0..i
    def solve(i: int) -> int:
        # an empty prefix has nothing to offer
        if i < 0:
            return 0
        # with just index 0 available, the best move is to take it
        if i == 0:
            return nums[0]
        # Choice 1: TAKE nums[i] — index i-1 becomes forbidden, so recurse on i-2
        take = nums[i] + solve(i - 2)
        # Choice 2: SKIP nums[i] — the whole prefix 0..i-1 stays available
        skip = solve(i - 1)
        # keep whichever choice earns more money
        return max(take, skip)

    # the answer uses the full array: the prefix ending at the last index
    return solve(len(nums) - 1)

def rob(nums: List[int]) -> int:
    n = len(nums)  # number of houses on the circle
    # a lone house has no neighbour — rob it outright
    if n == 1:
        return nums[0]

    best = 0  # best loot found over all legal subsets
    # every subset of houses can be encoded as a bitmask: bit i set = rob house i
    for mask in range(1 << n):
        valid = True  # assume legal until an adjacent pair is found
        for i in range(n):
            # neighbour on a circle: house (i+1) % n — the last wraps to the first
            if (mask >> i) & 1 and (mask >> ((i + 1) % n)) & 1:
                valid = False  # two adjacent houses robbed -> alarm
                break
        if valid:
            # sum the money of every robbed house in this legal plan
            total = sum(nums[i] for i in range(n) if (mask >> i) & 1)
            best = max(best, total)  # keep the richest legal plan
    return best

def frogJump(heights: List[int]) -> int:
    # solve(i) = minimum energy for the frog to reach stone i from stone 0
    def solve(i: int) -> int:
        # the frog starts on stone 0 — no energy spent yet
        if i == 0:
            return 0
        # arrive with a single hop from stone i-1, paying the height gap
        one = solve(i - 1) + abs(heights[i] - heights[i - 1])
        # arrive with a double jump from stone i-2 — only legal if it exists
        two = float('inf')  # sentinel: impossible at i == 1
        if i > 1:
            two = solve(i - 2) + abs(heights[i] - heights[i - 2])
        # the cheaper arrival wins
        return min(one, two)

    # answer: cheapest way to stand on the last stone
    return solve(len(heights) - 1)

def frogJumpK(heights: List[int], k: int) -> int:
    # solve(i) = minimum energy to travel from stone 0 to stone i
    def solve(i: int) -> int:
        # the frog starts on stone 0 — nothing spent yet
        if i == 0:
            return 0
        best = float('inf')  # cheapest arrival found so far
        # the final jump could have started at any of the k stones behind i
        for j in range(1, k + 1):
            # stone i-j must actually exist — stop at the left edge
            if i - j < 0:
                break
            # route cost: solve the launch stone first, then pay the height gap
            best = min(best, solve(i - j) + abs(heights[i] - heights[i - j]))
        return best

    # answer: cheapest way to stand on the last stone
    return solve(len(heights) - 1)

def frogJumpK(heights: List[int], k: int) -> int:
    memo = {}  # stone index -> min energy to reach it (computed once)

    def solve(i: int) -> int:
        # base: the frog starts on stone 0 for free
        if i == 0:
            return 0
        # cached? return the stored answer instead of recursing again
        if i in memo:
            return memo[i]
        best = float('inf')  # cheapest arrival found so far
        # try every legal launch stone among the k stones behind i
        for j in range(1, k + 1):
            if i - j < 0:
                break  # ran off the left edge — no more candidates
            # cost = cheapest way to reach the launch stone + this jump
            best = min(best, solve(i - j) + abs(heights[i] - heights[i - j]))
        memo[i] = best  # store before returning: each stone solved once
        return best

    return solve(len(heights) - 1)

def climbStairs(n: int) -> int:
    # solve(step) = number of distinct ways to climb exactly `step` stairs
    def solve(step: int) -> int:
        # base cases: 1 way to stay at the bottom, 1 way to reach step 1
        if step <= 1:
            return 1
        # the LAST move was either a 1-step (from step-1) or a 2-step (from step-2);
        # those two families of paths never overlap, so their counts add up
        return solve(step - 1) + solve(step - 2)

    # count all ways to reach the top step n
    return solve(n)

def climbStairs(n: int) -> int:
    memo = {}  # step -> number of ways (each computed exactly once)

    def solve(step: int) -> int:
        # base cases: one way to stand at step 0, one way to reach step 1
        if step <= 1:
            return 1
        # already counted this step? reuse the cached answer
        if step in memo:
            return memo[step]
        # disjoint families: last move 1-step vs last move 2-step
        memo[step] = solve(step - 1) + solve(step - 2)  # store, then return
        return memo[step]

    return solve(n)  # total ways to reach the top step n

def preorderTraversal(root: Optional[TreeNode]) -> List[int]:
    result = []                  # collects values in Root -> Left -> Right order
    # An empty tree produces an empty traversal
    if not root:
        return result

    # The stack holds nodes whose subtrees are still waiting to be visited;
    # we seed it with the root, the very first node preorder prints
    stack = [root]

    # Keep working while at least one subtree is unprocessed
    while stack:
        node = stack.pop()           # take the most recently deferred node
        result.append(node.val)      # visit it IMMEDIATELY — that is "pre"-order
        # Push RIGHT before LEFT: the stack is LIFO, so the left child
        # pops first — exactly the order preorder demands
        if node.right:
            stack.append(node.right) # right child waits underneath
        if node.left:
            stack.append(node.left)  # left child sits on top, popped next

    return result                    # e.g. [1, 2, 4, 5, 3] for the sample tree

def topoSort(V, adj):
    # order collects the final topological sequence, one vertex per round
    order = []
    # placed[u] is True once u has been added to the order
    placed = [False] * V
    # we must place all V vertices, so run exactly V rounds
    for _ in range(V):
        # scan for a vertex whose every incoming edge starts at a placed vertex
        for u in range(V):
            if placed[u]:
                continue  # u is already in the order, skip it
            # look for any UNPLACED vertex x that still points into u
            blocked = False
            for x in range(V):
                if not placed[x] and u in adj[x]:
                    blocked = True  # edge x -> u exists and x is not placed yet
                    break
            # no unplaced prerequisite remains -> u is safe to emit next
            if not blocked:
                order.append(u)
                placed[u] = True
                break
    return order

def topoSort(V, adj):
    # order collects the final topological sequence
    order = []
    placed = [False] * V  # placed[u]: u has already been emitted
    # exactly one vertex gets placed per round -> V rounds total
    for _ in range(V):
        # recompute in-degrees of the REMAINING graph from scratch
        indeg = [0] * V
        for u in range(V):
            if placed[u]:
                continue  # deleted vertices contribute no edges any more
            for v in adj[u]:
                if not placed[v]:
                    indeg[v] += 1  # a still-live edge u -> v
        # pick the first unplaced vertex with zero remaining in-degree
        for u in range(V):
            if not placed[u] and indeg[u] == 0:
                order.append(u)   # safe: nothing unplaced points at u
                placed[u] = True  # "delete" u and all its outgoing edges
                break
    return order

def isBipartite(graph):
    n = len(graph)  # number of vertices
    # try every possible way to split the vertices into two sets: 2^n masks
    for mask in range(1 << n):
        # bit u of mask decides u's set: 0 or 1
        ok = True
        # verify that EVERY edge crosses between the two sets
        for u in range(n):
            for v in graph[u]:
                # extract each endpoint's set from the mask
                if (mask >> u) & 1 == (mask >> v) & 1:
                    ok = False  # an edge stays inside one set -> split fails
                    break
            if not ok:
                break
        # found one split where all edges cross -> bipartite
        if ok:
            return True
    # no split of the vertices works
    return False

def shortestPathDAG(V, edges, src=0):
    # build the adjacency list: u -> list of (v, w) weighted edges
    adj = [[] for _ in range(V)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # ---- phase 1: topological order via DFS ----
    visited = [False] * V
    order = []  # vertices in reverse topological order

    def dfs(u):
        visited[u] = True  # mark u before exploring below it
        for v, _ in adj[u]:
            if not visited[v]:
                dfs(v)  # finish all of u's descendants first
        order.append(u)  # u enters only after everything it reaches

    # cover disconnected parts of the DAG too
    for u in range(V):
        if not visited[u]:
            dfs(u)
    order.reverse()  # flip to get a true topological order

    # ---- phase 2: relax edges in topological order ----
    INF = float('inf')
    dist = [INF] * V  # INF = "not reachable so far"
    dist[src] = 0  # the source costs nothing to reach
    for u in order:
        # vertices still at INF cannot improve anyone
        if dist[u] != INF:
            for v, w in adj[u]:
                # does the path src -> ... -> u -> v beat the best known?
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w  # yes: record the shorter cost

    # convention: report unreachable vertices as -1
    return [d if d != INF else -1 for d in dist]

def dijkstra(V, adj, src):
    INF = float('inf')
    # dist[u] = best known cost from src to u so far
    dist = [INF] * V
    dist[src] = 0  # the source is free to reach
    # finalized[u] = True once u's distance can never improve again
    finalized = [False] * V
    # each round finalizes exactly one vertex -> at most V rounds
    for _ in range(V):
        # linear scan: find the CLOSEST vertex not yet finalized
        u, best = -1, INF
        for x in range(V):
            if not finalized[x] and dist[x] < best:
                u, best = x, dist[x]
        # nothing reachable remains -> every leftover vertex is cut off
        if u == -1:
            break
        finalized[u] = True  # u's distance is now provably final
        # relax every edge leaving u
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w  # found a cheaper route to v
    return dist

class Trie:
    def __init__(self):
        # The most literal storage possible: keep every inserted word in a list.
        self.words = []                      # duplicates are kept, order does not matter

    def insert(self, word: str) -> None:
        self.words.append(word)              # O(1): just remember one more copy

    def countWordsEqualTo(self, word: str) -> int:
        # Walk the whole bag and count exact matches.
        return sum(1 for w in self.words if w == word)   # O(N) comparisons of length L

    def countWordsStartingWith(self, prefix: str) -> int:
        # str.startswith compares up to len(prefix) characters per stored word.
        return sum(1 for w in self.words if w.startswith(prefix))   # O(N * L)

    def erase(self, word: str) -> None:
        if word in self.words:               # guard: erasing a missing word is a no-op
            self.words.remove(word)          # removes ONE occurrence, O(N) shift

from collections import Counter

class Trie:
    def __init__(self):
        # Two hash maps instead of a tree: one for whole words, one for prefixes.
        self.word_count = Counter()          # word -> how many copies were inserted
        self.prefix_count = Counter()        # prefix string -> how many words start with it

    def insert(self, word: str) -> None:
        self.word_count[word] += 1           # one more copy of the exact word
        # Register EVERY prefix, including the empty one so that "" counts all words.
        for i in range(len(word) + 1):
            self.prefix_count[word[:i]] += 1  # word[:i] builds a fresh string: O(i) work

    def countWordsEqualTo(self, word: str) -> int:
        return self.word_count[word]         # Counter returns 0 for unseen keys

    def countWordsStartingWith(self, prefix: str) -> int:
        return self.prefix_count[prefix]     # answer was precomputed at insert time

    def erase(self, word: str) -> None:
        if self.word_count[word] == 0:       # guard so counters never go negative
            return
        self.word_count[word] -= 1           # undo the exact-word bump
        for i in range(len(word) + 1):
            self.prefix_count[word[:i]] -= 1  # undo every prefix bump, mirroring insert
